package com.vandorlabs.neoforge.copifier;
import com.google.gson.*;
import com.vandorlabs.neoforge.screen.*;
import com.vandorlabs.screen.ScreenFamily;
import java.nio.file.*;
import java.io.*;
import java.util.zip.GZIPInputStream;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Installed canonical owners replay actual Source callbacks without copying their physical chip. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierScreenWorldChecks {
 private static final BlockPos POS=new BlockPos(22300,82,22300);private static int checks;
 private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Copied Screen: "+text);}
 private static NativeScreenEntity put(ServerLevel world,BlockPos pos,ScreenFamily family,int meta,CompoundTag raw){world.getChunkAt(pos);world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);var block=NativeScreenRegistrations.BLOCKS.get(family).get();world.setBlock(pos,block.state(family.decode(meta)),18);var owner=(NativeScreenEntity)world.getBlockEntity(pos);var input=raw.copy();input.putString("CopiedScreenMarker","retained");input.putByteArray("CopiedScreenPayload",new byte[65536]);owner.loadWithComponents(input,world.registryAccess());owner.onLoad();need(!owner.inert(),"usable "+family+" input="+raw);return owner;}
 private static void write(ServerLevel world)throws Exception{var toolActor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new java.util.UUID(0,1898),"CopiedScreens"));toolActor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);toolActor.setPos(POS.getX()+.5,POS.getY(),POS.getZ()-2);int count=0;var chipSaved=new java.util.EnumMap<ScreenFamily,CompoundTag>(ScreenFamily.class);try(var lines=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.copifierScreenReference")))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();var family=ScreenFamily.fromId(row.get("block").getAsString());var owner=put(world,POS,family,row.get("meta").getAsInt(),TagParser.parseTag(row.get("target").getAsString()));var state=owner.getBlockState();var values=TagParser.parseTag(row.get("values").getAsString());var clipboard=values.copy();var before=owner.saveWithoutMetadata(world.registryAccess());int page=owner.chipPage();var chip=owner.visual().chip();need(NativeCopifierHousingWorld.capture(world,POS,toolActor,net.minecraft.core.Direction.NORTH).equals(TagParser.parseTag(row.get("before").getAsString())),"Source initial case="+count);need(NativeCopifierHousingWorld.applySingle(world,POS,toolActor,net.minecraft.core.Direction.NORTH,values)==row.get("applied").getAsBoolean(),"Source applicability case="+count);var expected=TagParser.parseTag(row.get("after").getAsString());var actual=NativeCopifierScreenEdit.capture(owner);need(expected.equals(actual),"Source final case="+count+" values="+values+" expected="+expected+" actual="+actual);var saved=owner.saveWithoutMetadata(world.registryAccess());var sourceSaved=TagParser.parseTag(row.get("saved").getAsString());for(int slot=0;slot<2;slot++){var key=slot==0?"RedstonePrimary":"RedstoneSecondary";var wanted=NativeScreenControls.read(sourceSaved.getCompound(key),family.standaloneControlRows(slot));var wantTag=new CompoundTag();wanted.write(wantTag);var actualTag=new CompoundTag();owner.controls(slot).write(actualTag);need(wantTag.equals(actualTag),"Source row runtime case="+count+" slot="+slot+" expected="+sourceSaved.getCompound(key)+" actual="+saved.getCompound(key));}need(java.util.Objects.equals(before.get("ScreenChipReader"),saved.get("ScreenChipReader")),"sole physical chip unchanged case="+count);need(owner.chipPage()==page&&(chip==null||owner.visual().chip()==null||owner.visual().chip().journal==chip.journal),"prepared chip identity/page unchanged case="+count);if(saved.contains("ScreenChipReader"))chipSaved.putIfAbsent(family,saved.copy());need(world.getBlockEntity(POS)==owner&&owner.getBlockState()==state&&values.equals(clipboard),"installed identity/state/clipboard case="+count);need(saved.getString("CopiedScreenMarker").equals("retained")&&saved.getByteArray("CopiedScreenPayload").length==65536,"opaque retention case="+count);var dto=owner.getUpdateTag(world.registryAccess());need(!dto.contains("ScreenChipReader")&&!dto.contains("CopiedScreenPayload")&&!dto.toString().contains("private:screen"),"public privacy case="+count);count++;}}need(count==5866,"full Source matrix");
 for(var family:ScreenFamily.values()){var chipPos=POS.east(20+family.ordinal());need(chipSaved.containsKey(family),"physical chip Source coverage "+family);var chipOwner=put(world,chipPos,family,2,chipSaved.get(family));need(chipOwner.saveWithoutMetadata(world.registryAccess()).getCompound("ScreenChipReader").contains("InsertedToken"),"saved one embedded chip "+family);world.setChunkForced(chipPos.getX()>>4,chipPos.getZ()>>4,true);var pos=POS.east(5+family.ordinal());var owner=put(world,pos,family,2,new CompoundTag());var edit=new CompoundTag();edit.putInt("wall_texture",7);edit.putInt("display_mode",2);need(owner.configureCopied(edit),"restart edit "+family);var saved=owner.saveWithoutMetadata(world.registryAccess());var invalid=edit.copy();invalid.putInt("texture_layout",99);need(!owner.configureCopied(invalid)&&owner.saveWithoutMetadata(world.registryAccess()).equals(saved),"atomic invalid preflight "+family);need(!java.util.concurrent.CompletableFuture.supplyAsync(()->owner.configureCopied(edit)).join(),"worker refusal "+family);world.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);}
 }
 private static void read(ServerLevel world){for(var family:ScreenFamily.values()){var chipOwner=(NativeScreenEntity)world.getBlockEntity(POS.east(20+family.ordinal()));need(chipOwner!=null&&!chipOwner.inert()&&com.vandorlabs.neoforge.credentials.NativeCredentialItems.readStack(chipOwner.saveWithoutMetadata(world.registryAccess()).getCompound("ScreenChipReader").getCompound("InsertedToken"),world.registryAccess()).getCount()==1,"one usable embedded chip after restart "+family);var owner=(NativeScreenEntity)world.getBlockEntity(POS.east(5+family.ordinal()));need(owner!=null&&!owner.inert()&&NativeCopifierScreenEdit.capture(owner).getInt("wall_texture")==7,"saved copied choices "+family);need(owner.saveWithoutMetadata(world.registryAccess()).getByteArray("CopiedScreenPayload").length==65536,"saved opaque payload "+family);}}
 @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception{var phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.equals("copifier-screen-write")&&!phase.equals("copifier-screen-read"))return;var world=event.getServer().overworld();if(phase.endsWith("write"))write(world);else read(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][copifier-screen] "+(phase.endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
